css:
:root.theme-ext-theme-aurora-mist {
  --bg: #0b1021;
  --bg-surface: #0f162b;
  --bg-surface-2: #131a33;
  --text: #e6f1ff;
  --text-muted: #c3d5ff;
  --accent: #9ae6ff;
  --accent-strong: #7cd4ff;
  --border: #1c2847;
}
.theme-ext-theme-aurora-mist body {
  background: radial-gradient(circle at 20% 20%, rgba(85, 190, 255, 0.1), transparent 30%),
              radial-gradient(circle at 80% 10%, rgba(120, 90, 255, 0.12), transparent 28%),
              var(--bg);
  color: var(--text);
}
.theme-ext-theme-aurora-mist .card { border-color: var(--border); background: linear-gradient(135deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01)) var(--bg-surface); box-shadow: 0 10px 30px rgba(0,0,0,0.35); }
.theme-ext-theme-aurora-mist a { color: var(--accent); }
